package com.internhub.repository;
import com.internhub.entity.Internship; import com.internhub.entity.InternshipStatus; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.Optional;
public interface InternshipRepository extends MongoRepository<Internship, Long> { Page<Internship> findByStatus(InternshipStatus status, Pageable pageable); Page<Internship> findByCompanyId(Long companyId, Pageable pageable); Optional<Internship> findByIdAndCompanyId(Long id, Long companyId); long countByStatus(InternshipStatus status); }
